/**
 * App Router Handler
 *
 * Handles App Router route.ts files with HTTP method support.
 */
import { resolveAppRouteFile } from "./app-router-resolver.js";
import { applySecurityHeaders } from "./security-headers.js";
import { applyCORSHeaders } from "../../../../security/index.js";
import { serverLogger } from "../../../../utils/index.js";
import { methodNotAllowed } from "../../../../platform/compat/http/responses.js";
import { createApplicationRequest } from "../../../../security/http/application-request.js";
import { requiresIsolatedProjectRuntime } from "../../../../security/project-locality.js";
import { createErrorResponseFromDefinition, PROJECT_EXECUTION_UNAVAILABLE, } from "../../../../errors/index.js";
const logger = serverLogger.component("app-router-api-handler");
const HTTP_METHODS = ["GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"];
function getAllowedMethods(mod) {
    return HTTP_METHODS.filter((m) => typeof mod[m] === "function");
}
function resolveHandlerFunction(mod, method) {
    const methodFn = mod[method];
    if (typeof methodFn === "function")
        return [methodFn, false];
    if (method === "HEAD" && typeof mod.GET === "function")
        return [mod.GET, true];
    return [undefined, false];
}
export async function handleAppRouter(req, pathname, ctx) {
    try {
        if (requiresIsolatedProjectRuntime(ctx)) {
            const unavailable = createErrorResponseFromDefinition(PROJECT_EXECUTION_UNAVAILABLE, {
                detail: "Shared runtimes require a dedicated isolated project runtime for API execution",
                instance: pathname,
            });
            const headers = new Headers(unavailable.headers);
            headers.set("cache-control", "no-store");
            await applyCORSHeaders({
                request: req,
                headers,
                config: ctx.securityConfig?.cors,
            });
            applySecurityHeaders(headers, ctx, req);
            return new Response(req.method === "HEAD" ? null : unavailable.body, {
                status: unavailable.status,
                statusText: unavailable.statusText,
                headers,
            });
        }
        const match = await resolveAppRouteFile(pathname, ctx);
        if (!match)
            return null;
        const mod = (await import(`file://${match.file}`));
        const method = req.method.toUpperCase();
        const [fn, headShim] = resolveHandlerFunction(mod, method);
        if (!fn)
            return methodNotAllowed(getAllowedMethods(mod));
        const res = await fn(createApplicationRequest(req, {
            denyHeaders: ctx.applicationIdentityHeaderNames,
        }), {
            params: match.params,
            identity: ctx.applicationIdentity ?? null,
        });
        const headers = new Headers(res.headers);
        await applyCORSHeaders({
            request: req,
            headers,
            config: ctx.securityConfig?.cors,
        });
        applySecurityHeaders(headers, ctx, req);
        if (headShim)
            return new Response(null, { status: res.status, headers });
        return new Response(res.body, { status: res.status, headers });
    }
    catch (error) {
        logger.error("Failed to handle request", error);
        return null;
    }
}
